// =====================================================================
//  WELT 5 – DER WALD – GERÜST
//  Informatik LK · Online-IDE · Algo Quest · Level 5.1 bis 5.4
//
//  Hinter dem Hafen beginnt der Wald. Hier wachsen keine Listen mehr,
//  sondern Baeume: Jeder Knoten hat zwei Teilbaeume, und jeder
//  Teilbaum ist wieder ein Baum. Genau deshalb laesst sich fast alles
//  im Wald REKURSIV erledigen. Fuer das Dungeon-Spiel baust du zwei
//  Spielmodule: den Akinator, ein Monsterquiz, das aus seinen Fehlern
//  lernt, und die Item-Datenbank, in der jedes Item ueber seine Nummer
//  in einem binaeren Suchbaum blitzschnell gefunden wird.
//
//  ANLEITUNG:
//  0. BIBLIOTHEK EINSCHALTEN (einmal pro Workspace, sonst kennt die IDE
//     BinTree nicht):
//     Workspace in der Liste links mit der RECHTEN Maustaste anklicken
//     -> "Einstellungen" -> Haekchen bei "Niedersachsen" setzen -> OK.
//     Danach sind die Abitur-Klassen Stack, Queue, DynArray und BinTree
//     da.
//
//  1. Du arbeitest NUR im Abschnitt "DEIN TEIL". Ueber jeder Methode
//     stehen ihre Signatur in Abi-Notation und eine kurze Beschreibung.
//     Ersetze die Zeilen "// TODO Level 5.x" und die vorlaeufigen
//     return-Anweisungen durch deine Loesung. Methoden mit dem Hinweis
//     "rekursive Hilfsmethode" gehoeren zur Aufgabe dazu: Die Methode
//     darueber ruft sie nur auf. In Akinator sind das Attribut baum,
//     der Konstruktor Akinator(b: BinTree) und getBaum() vorgegeben.
//
//  2. Tests starten: Oeffne den Reiter "Testrunner" und klicke auf den
//     gruenen Dreieckspfeil neben einer Testklasse (alle Tests dieses
//     Levels) oder neben einem einzelnen Test. Gruen = bestanden,
//     rot = noch nicht bestanden. Lies bei roten Tests die Meldung!
//     Baeume stehen dort in Klammerform, z. B. "8(3(1,6),10(-,14))":
//     Wurzel 8, links der Teilbaum 3(1,6), rechts 10 mit leerem linken
//     Teilbaum "-" und dem Blatt 14. Beginnt die Meldung mit
//     "LAUFZEITFEHLER", ist dein Programm abgestuerzt - meistens fehlt
//     der Basisfall if (b.isEmpty()). Haengt der Testrunner, hast du
//     eine Endlosschleife oder eine Rekursion ohne Ende.
//
//  3. Die Level und ihre Testklassen:
//
//      Level  DS         Klasse      Testklasse
//      -------------------------------------------------------------------
//      5.1    31         Baum        L51BaumTest
//                        Knoten zaehlen, pre-/in-/postorder, Hoehe,
//                        Blaetter, Summe, Termbaum, spiegeln
//      5.2    32         Rekursiv    L52RekursivTest
//                        suchen, Maximum, sammeln in DynArray, Ebenen,
//                        Pfad, Gleichheit
//      5.3    33 (Kuer)  Akinator    L53AkinatorTest
//                        Entscheidungsbaum: raten, lernen, zaehlen;
//                        Level-Order mit Schlange
//      5.4    34 – 35    Suchbaum    L54SuchbaumTest
//                        BST: suchen, einfuegen, Minimum, Vergleiche,
//                        isBST, ausgeglichen bauen, Nachfolger
//
//     In jedem Level gibt es drei Stufen. Du erkennst sie am Anfang des
//     Testnamens:
//          basis_...         Basis
//          erweiterung_...   Erweiterung
//          experte_...       Experte
//     Eine Stufe ist geschafft, wenn ALLE Tests mit diesem Anfang gruen
//     sind. Am Anfang ist noch kein Test gruen.
//
//  4. INFOKASTEN: CASTEN BEI BINTREE
//     BinTree speichert seinen Inhalt als Object. Was du mit getItem()
//     herausholst, musst du in den richtigen Typ umwandeln (casten):
//         int x = (Integer) b.getItem();      // BinTree vom Inhaltstyp Ganzzahl
//         String s = (String) t.getItem();    // BinTree vom Inhaltstyp Zeichenkette
//         BinTree k = (BinTree) q.dequeue();  // Schlange vom Inhaltstyp BinTree
//     Hineinlegen geht ohne Cast: new BinTree(5); b.setItem("Troll");
//     Den Variablentyp schreibst du OHNE spitze Klammern:
//         BinTree b = new BinTree();    Queue q = new Queue();
//     Zum Ausgeben brauchst du keinen Cast: b.getItem() + " " ergibt
//     eine Zeichenkette ("8 ").
//     Ohne Cast meldet die IDE einen Fehler ("Object kann nicht in int
//     umgewandelt werden"). Ein FALSCHER Cast (z. B. (Integer) im
//     Termbaum) fuehrt erst beim Ausfuehren zum Laufzeitfehler.
//
//  5. ABI-CHECK FUER JEDE BAUM-METHODE: "Leer? Blatt?"
//     - Leer?  getItem, getLeft, getRight, isLeaf, setLeft und setRight
//       auf einem LEEREN Baum sind ein Laufzeitfehler. Deshalb beginnt
//       JEDE rekursive Baum-Methode mit dem Basisfall:
//           if (b.isEmpty()) { return ...; }
//       Die Tests rufen jede Methode auch mit dem leeren Baum auf!
//     - Blatt?  isLeaf() erst NACH isEmpty() fragen (isLeaf auf einem
//       leeren Baum ist ebenfalls ein Laufzeitfehler).
//     - Nie null!  Ein leerer Teilbaum ist new BinTree(), nicht null.
//       Methoden, die einen Baum oder eine DynArray liefern, geben nie
//       null zurueck.
//     - Rekursion: Der Aufruf geht immer an einen TEILBAUM
//       (b.getLeft(), b.getRight()) - so wird der Baum kleiner und der
//       Basisfall wird sicher erreicht.
//
//  6. VORGEGEBEN (nicht veraendern): die Klassen Baumschule (die
//     Testbaeume) und Testhilfe sowie in Akinator das Attribut baum, der
//     Konstruktor Akinator(b: BinTree) und getBaum(). Die Testklassen
//     darfst du NICHT veraendern - sonst zaehlt der Test nicht. Du glaubst,
//     ein Test ist falsch? Melde ihn deiner Lehrkraft (Bug-Meldung).
//
//  7. Mit dem gruenen Startknopf oben laeuft das Hauptprogramm ganz unten
//     (ein Streifzug durch den Wald mit Konsolenausgabe, darin eine
//     Runde Akinator mit festen Antworten).
//
//  SPIELREGELN (Begriffe wie im Abitur):
//  - Wurzel: der oberste Knoten. Blatt: Knoten ohne Kinder (beide
//    Teilbaeume leer). Innerer Knoten: Knoten mit mindestens einem Kind.
//  - Ebene: Die Wurzel liegt auf Ebene 0, ihre Kinder auf Ebene 1 usw.
//  - Hoehe: leerer Baum 0, Blatt 1, sonst 1 + die groessere Hoehe der
//    beiden Teilbaeume (= Anzahl der Ebenen).
//  - Preorder: Wurzel, links, rechts. Inorder: links, Wurzel, rechts.
//    Postorder: links, rechts, Wurzel. Levelorder: Ebene fuer Ebene.
//  - Binaerer Suchbaum (BST): Fuer JEDEN Knoten sind alle Werte im
//    linken Teilbaum kleiner und alle Werte im rechten Teilbaum groesser.
//  - Zeichenketten IMMER mit equals vergleichen, nie mit ==. Erlaubt
//    sind nur length(), charAt(i), substring(a, b), +, equals,
//    contains, compareTo und (int) c bzw. (char) n - KEIN
//    Integer.parseInt (die Umwandlung "12" -> 12 schreibst du selbst).
// =====================================================================


// ---------------------------------------------------------------------
//  GERÜST – hier nichts veraendern
// ---------------------------------------------------------------------
//  Baumschule: die Testbaeume der Welt 5 (in allen Leveln, auf den
//              Arbeitsblaettern und im Boss benutzt). Jeder Aufruf
//              liefert einen NEUEN Baum - du darfst ihn veraendern.
//  Testhilfe:  zeigt Baeume und dynamische Reihungen als Text (fuer die
//              Meldungen der Tests) und meldet Laufzeitfehler mit einem
//              Hinweis.
//  Du darfst beide Klassen auch im Hauptprogramm benutzen.
// ---------------------------------------------------------------------

//  Die Testbaeume (ja = links, nein = rechts beim Monsterquiz):
//
//  beispielBST()            zahlenbaum()            termbaum()
//  (BST: 8, 3, 10, 1, 6,    (KEIN BST,              "(3+4)*(5-2)"
//   14, 4, 7, 13 eingefuegt) Duplikat 9)
//          8                       5                     *
//        /   \                   /   \                 /   \
//       3     10                9     4               +     -
//      / \      \              / \     \             / \   / \
//     1   6      14           2   7     9           3   4 5   2
//        / \    /                      /
//       4   7  13                     1
//
//  entartet(): 1 -> 2 -> 3 -> 4 -> 5 (jeder Knoten hat nur ein rechtes Kind)
//
//  monsterquiz():                 Kann es fliegen?
//                              ja /              \ nein
//                    Speit es Feuer?          Lebt es im Wasser?
//                    ja /     \ nein          ja /         \ nein
//                   Drache    Greif         Kraken         Troll
//
//  leer(): leerer Baum      blatt(x): ein einzelnes Blatt mit dem Wert x

class Baumschule {

    // knoten(inhalt: Object, links: BinTree, rechts: BinTree): BinTree
    // Neuer Knoten mit dem Inhalt und den beiden Teilbaeumen.
    public static BinTree knoten(Object inhalt, BinTree links, BinTree rechts) {
        BinTree b = new BinTree(inhalt);
        b.setLeft(links);
        b.setRight(rechts);
        return b;
    }

    // blatt(x: Ganzzahl): BinTree  - ein Knoten mit zwei leeren Teilbaeumen
    public static BinTree blatt(int x) {
        return new BinTree(x);
    }

    // leer(): BinTree  - der leere Baum
    public static BinTree leer() {
        return new BinTree();
    }

    // Der Beispiel-Suchbaum: entsteht durch Einfuegen von
    // 8, 3, 10, 1, 6, 14, 4, 7, 13 (in dieser Reihenfolge).
    public static BinTree beispielBST() {
        BinTree links = knoten(3, blatt(1), knoten(6, blatt(4), blatt(7)));
        BinTree rechts = knoten(10, leer(), knoten(14, blatt(13), leer()));
        return knoten(8, links, rechts);
    }

    // Ein Zahlenbaum, der KEIN Suchbaum ist (9 kommt zweimal vor).
    public static BinTree zahlenbaum() {
        BinTree links = knoten(9, blatt(2), blatt(7));
        BinTree rechts = knoten(4, leer(), knoten(9, blatt(1), leer()));
        return knoten(5, links, rechts);
    }

    // Entarteter Suchbaum: 1, 2, 3, 4, 5 eingefuegt -> rechte Kette.
    public static BinTree entartet() {
        BinTree b = blatt(5);
        for (int i = 4; i >= 1; i--) {
            b = knoten(i, leer(), b);
        }
        return b;
    }

    // Termbaum zu (3+4)*(5-2): Inhaltstyp Zeichenkette.
    // Innere Knoten: Rechenzeichen "+", "-", "*", "/"; Blaetter: Zahlen.
    public static BinTree termbaum() {
        BinTree plus = knoten("+", new BinTree("3"), new BinTree("4"));
        BinTree minus = knoten("-", new BinTree("5"), new BinTree("2"));
        return knoten("*", plus, minus);
    }

    // Startbaum des Akinator-Monsterquiz: innere Knoten = Fragen,
    // Blaetter = Monster; ja -> links, nein -> rechts.
    public static BinTree monsterquiz() {
        BinTree fliegt = knoten("Speit es Feuer?", new BinTree("Drache"), new BinTree("Greif"));
        BinTree laeuft = knoten("Lebt es im Wasser?", new BinTree("Kraken"), new BinTree("Troll"));
        return knoten("Kann es fliegen?", fliegt, laeuft);
    }
}


class Testhilfe {

    // Klammerdarstellung eines Baums (fuer die Meldungen der Tests):
    //   leerer Baum "-", Blatt "7", sonst inhalt(links,rechts)
    //   beispielBST -> "8(3(1,6(4,7)),10(-,14(13,-)))"
    public static String klammer(BinTree b) {
        if (b == null) {
            return "null";
        }
        if (b.isEmpty()) {
            return "-";
        }
        if (b.isLeaf()) {
            return "" + b.getItem();
        }
        return b.getItem() + "(" + klammer(b.getLeft()) + "," + klammer(b.getRight()) + ")";
    }

    // Inhalt einer dynamischen Reihung als Text, z. B. "[1, 3, 4]".
    public static String text(DynArray d) {
        if (d == null) {
            return "null";
        }
        String t = "[";
        for (int i = 0; i < d.getLength(); i++) {
            if (i > 0) {
                t = t + ", ";
            }
            t = t + d.getItem(i);
        }
        return t + "]";
    }

    // Neue Zeichenkette mit demselben Inhalt wie s (Zeichen fuer Zeichen
    // zusammengesetzt). Damit pruefen die Tests, dass du Zeichenketten mit
    // equals vergleichst und nicht mit ==.
    public static String kopie(String s) {
        String t = "";
        for (int i = 0; i < s.length(); i++) {
            t = t + s.charAt(i);
        }
        return t;
    }

    // Die Tests fangen Laufzeitfehler (Exceptions) ab und melden sie mit
    // einem Hinweis. In einer richtigen Loesung tritt NIE ein Laufzeitfehler
    // auf - auch nicht beim leeren Baum!
    public static void laufzeitfehler(RuntimeException e) {
        String meldung = " (Meldung der IDE: " + e.getMessage() + ")";
        try {
            throw e;
        } catch (IllegalStateException x) {
            fail("LAUFZEITFEHLER: getItem, getLeft, getRight, isLeaf, setLeft oder setRight auf einem LEEREN Baum - Basisfall if (b.isEmpty()) vergessen oder an die falsche Stelle gesetzt?" + meldung);
        } catch (IllegalArgumentException x) {
            fail("LAUFZEITFEHLER: null an setItem, setLeft oder setRight bzw. an append uebergeben - nimm new BinTree() fuer einen leeren Teilbaum." + meldung);
        } catch (IndexOutOfBoundsException x) {
            fail("LAUFZEITFEHLER: Index ausserhalb - bei charAt/substring gilt 0 <= i < length(), bei Reihungen 0 <= i < length. Schleifengrenze bzw. lo/hi pruefen!" + meldung);
        } catch (ClassCastException x) {
            fail("LAUFZEITFEHLER: falscher Cast - (Integer) fuer Zahlenbaeume, (String) fuer Termbaum und Monsterquiz, (BinTree) fuer die Schlange in levelorder." + meldung);
        } catch (NullPointerException x) {
            fail("LAUFZEITFEHLER: Zugriff auf null - Attribut im Konstruktor nicht erzeugt? Liefert eine Methode noch null statt new BinTree() bzw. new DynArray()?" + meldung);
        } catch (RuntimeException x) {
            fail("LAUFZEITFEHLER" + meldung);
        }
    }
}


