            assertTrue(Rekursiv.istGleich(Baumschule.leer(), Baumschule.leer()), "istGleich: zwei leere Baeume sind gleich");
            assertFalse(Rekursiv.istGleich(Baumschule.beispielBST(), Baumschule.zahlenbaum()), "istGleich(beispielBST, zahlenbaum): false");
            BinTree a = Baumschule.knoten(1, Baumschule.blatt(2), Baumschule.leer());
            BinTree b = Baumschule.knoten(1, Baumschule.leer(), Baumschule.blatt(2));
            assertFalse(Rekursiv.istGleich(a, b), "istGleich(1(2,-), 1(-,2)): false - gleiche Werte, gleiche Preorder, aber andere STRUKTUR");
            assertFalse(Rekursiv.istGleich(Baumschule.blatt(1), Baumschule.blatt(2)), "istGleich(1, 2): false - verschiedene Werte");
            BinTree c = Baumschule.beispielBST();
            c.getRight().getRight().getLeft().setItem(12);
            assertFalse(Rekursiv.istGleich(Baumschule.beispielBST(), c), "istGleich: beispielBST mit 12 statt 13 ganz unten -> false");
            BinTree ausgeglichen = Baumschule.knoten(7, Baumschule.knoten(3, Baumschule.blatt(1), Baumschule.knoten(4, Baumschule.leer(), Baumschule.blatt(6))), Baumschule.knoten(10, Baumschule.blatt(8), Baumschule.knoten(13, Baumschule.leer(), Baumschule.blatt(14))));
            assertFalse(Rekursiv.istGleich(Baumschule.beispielBST(), ausgeglichen), "istGleich: gleiche Werte in gleicher Inorder-Reihenfolge, aber andere Struktur -> false");
            assertFalse(Rekursiv.istGleich(Baumschule.leer(), Baumschule.blatt(0)), "istGleich(leer, Blatt): false");
            assertFalse(Rekursiv.istGleich(Baumschule.blatt(0), Baumschule.leer()), "istGleich(Blatt, leer): false");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }
}


class L53AkinatorTest {

