            assertTrue(a.getBaum().isLeaf(), "Akinator('Drache'): baum ist ein Blatt");
            assertEquals("Drache", (String) a.getBaum().getItem(), "Akinator('Drache'): Inhalt des Blatts");
            assertEquals("Drache", a.raten(""), "raten('') bei nur einem Monster: 'Drache' (ohne eine Frage)");
            assertEquals("Drache", a.raten("jn"), "raten('jn') bei nur einem Monster: 'Drache' (ueberzaehlige Antworten ignorieren)");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
