            assertEquals("Drache", a.raten("jj"), "raten('jj'): fliegt, speit Feuer -> Drache");
            assertEquals("Greif", a.raten("jn"), "raten('jn'): fliegt, kein Feuer -> Greif");
            assertEquals("Kraken", a.raten("nj"), "raten('nj'): fliegt nicht, lebt im Wasser -> Kraken");
            assertEquals("Troll", a.raten("nn"), "raten('nn'): fliegt nicht, nicht im Wasser -> Troll");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
