            assertEquals("Troll", a.raten("nnj"), "raten('nnj'): Troll - ueberzaehlige Antworten werden ignoriert");
            assertEquals("Drache", a.raten("jjnn"), "raten('jjnn'): Drache");
            assertEquals("?", a.raten("j"), "raten('j'): zu wenige Antworten -> '?' (kein Laufzeitfehler bei charAt!)");
            assertEquals("?", a.raten(""), "raten(''): keine Antwort -> '?'");
