        }
    }

    @Test
    public void erweiterung_lernen() {
        try {
            Akinator a = new Akinator("Drache");
            a.lernen("", "Greif", "Speit es Feuer?", false);
            assertEquals("Speit es Feuer?(Drache,Greif)", Testhilfe.klammer(a.getBaum()), "lernen('', 'Greif', 'Speit es Feuer?', false): Die Wurzel wird zur Frage, neu (Greif) kommt nach RECHTS (nein)");
            assertEquals("Drache", a.raten("j"), "nach dem Lernen: raten('j') -> Drache");
            assertEquals("Greif", a.raten("n"), "nach dem Lernen: raten('n') -> Greif");
            Akinator b = new Akinator("Troll");
            b.lernen("", "Drache", "Kann es fliegen?", true);
            assertEquals("Kann es fliegen?(Drache,Troll)", Testhilfe.klammer(b.getBaum()), "lernen(..., true): neu (Drache) kommt nach LINKS (ja), alt (Troll) nach rechts");
            b.lernen("j", "Greif", "Speit es Feuer?", false);
            b.lernen("n", "Kraken", "Lebt es im Wasser?", true);
            assertEquals(Testhilfe.klammer(Baumschule.monsterquiz()), Testhilfe.klammer(b.getBaum()), "Durch dreimal lernen entsteht genau das Monsterquiz der Baumschule");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void erweiterung_lernen_tief() {
        try {
            Akinator a = new Akinator(Baumschule.monsterquiz());
            a.lernen("nn", "Golem", "Ist es aus Stein?", true);
            assertEquals("Golem", a.raten("nnj"), "Nach lernen('nn', 'Golem', 'Ist es aus Stein?', true): raten('nnj') -> Golem");
            assertEquals("Troll", a.raten("nnn"), "... raten('nnn') -> Troll");
            assertEquals("?", a.raten("nn"), "... raten('nn') -> '?' (jetzt fehlt eine Antwort)");
            assertEquals("Kraken", a.raten("nj"), "... raten('nj') -> Kraken (der Rest des Baums bleibt gleich)");
            a.lernen("jjn", "Phoenix", "Ist es ein Vogel?", true);
            assertEquals("Phoenix", a.raten("jjj"), "lernen('jjn', ...): Das Blatt Drache wird schon nach 'jj' erreicht, das 'n' ist ueberzaehlig -> raten('jjj') = Phoenix");
            assertEquals("Drache", a.raten("jjn"), "... raten('jjn') -> Drache");
            String vorher = Testhilfe.klammer(a.getBaum());
            a.lernen("j", "Harpyie", "Hat es Federn?", true);
            assertEquals(vorher, Testhilfe.klammer(a.getBaum()), "lernen('j', ...) reicht nicht bis zu einem Blatt -> nichts passiert");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void erweiterung_anzahlMonsterFragen() {
        try {
            Akinator a = new Akinator(Baumschule.monsterquiz());
            assertEquals(4, a.anzahlMonster(), "anzahlMonster(monsterquiz): 4 Blaetter");
            assertEquals(3, a.anzahlFragen(), "anzahlFragen(monsterquiz): 3 innere Knoten");
            a.lernen("nn", "Golem", "Ist es aus Stein?", true);
