            assertEquals(0, c.anzahlMonster(), "Leerer Baum: 0 Monster");
            assertEquals(0, c.anzahlFragen(), "Leerer Baum: 0 Fragen");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void experte_levelorder() {
        try {
            BinTree b = Baumschule.beispielBST();
