class L54SuchbaumTest {

    @Test
    public void basis_suche() {
        try {
            BinTree b = Baumschule.beispielBST();
            assertTrue(Suchbaum.suche(b, 8), "suche(beispielBST, 8): true (Wurzel)");
            assertTrue(Suchbaum.suche(b, 13), "suche(beispielBST, 13): true");
            assertTrue(Suchbaum.suche(b, 4), "suche(beispielBST, 4): true");
            assertTrue(Suchbaum.suche(b, 7), "suche(beispielBST, 7): true");
            assertFalse(Suchbaum.suche(b, 5), "suche(beispielBST, 5): false");
            assertFalse(Suchbaum.suche(b, 15), "suche(beispielBST, 15): false");
            assertFalse(Suchbaum.suche(b, 0), "suche(beispielBST, 0): false");
            assertTrue(Suchbaum.suche(Baumschule.entartet(), 5), "suche(entartet, 5): true");
            assertFalse(Suchbaum.suche(Baumschule.leer(), 8), "suche im leeren Baum: false");
            assertEquals("8(3(1,6(4,7)),10(-,14(13,-)))", Testhilfe.klammer(b), "suche darf den Baum NICHT veraendern");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void basis_suche_nurEinWeg() {
        try {
            // KEIN gueltiger Suchbaum: Die 5 steht rechts von der 8.
            // Eine richtige BST-Suche nach 5 geht links (5 < 8) und findet
            // sie NICHT. Wer beide Teilbaeume durchsucht, findet sie.
            BinTree falle = Baumschule.knoten(8, Baumschule.blatt(3), Baumschule.knoten(10, Baumschule.blatt(5), Baumschule.leer()));
            assertTrue(Suchbaum.suche(falle, 10), "suche(8(3,10(5,-)), 10): true");
            assertFalse(Suchbaum.suche(falle, 5), "suche darf in jedem Schritt nur EINEN Teilbaum betreten (5 < 8 -> nur links suchen) - sonst ist sie nicht schneller als enthaelt aus Level 5.2");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void basis_minimum() {
        try {
            assertEquals(1, Suchbaum.minimum(Baumschule.beispielBST()), "minimum(beispielBST): 1");
            assertEquals(1, Suchbaum.minimum(Baumschule.entartet()), "minimum(entartet): 1 (die Wurzel - links ist nichts)");
            BinTree b = Baumschule.knoten(5, Baumschule.knoten(2, Baumschule.leer(), Baumschule.blatt(3)), Baumschule.blatt(9));
            assertEquals(2, Suchbaum.minimum(b), "minimum von 5(2(-,3),9): 2 - das Minimum muss KEIN Blatt sein");
            assertEquals(42, Suchbaum.minimum(Baumschule.blatt(42)), "minimum eines Blatts: sein Wert");
            assertEquals(-1, Suchbaum.minimum(Baumschule.leer()), "minimum des leeren Baums: -1");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
