        try {
            BinTree b = new BinTree();
            int[] werte = {8, 3, 10, 1, 6, 14, 4, 7, 13};
            for (int i = 0; i < werte.length; i++) {
                Suchbaum.einfuegen(b, werte[i]);
            }
            assertEquals("8(3(1,6(4,7)),10(-,14(13,-)))", Testhilfe.klammer(b), "einfuegen von 8, 3, 10, 1, 6, 14, 4, 7, 13 in einen leeren Baum ergibt beispielBST");
            Suchbaum.einfuegen(b, 6);
            assertEquals("8(3(1,6(4,7)),10(-,14(13,-)))", Testhilfe.klammer(b), "einfuegen(b, 6): 6 ist schon da -> Duplikat, nichts aendern");
            Suchbaum.einfuegen(b, 5);
            assertEquals("8(3(1,6(4(-,5),7)),10(-,14(13,-)))", Testhilfe.klammer(b), "einfuegen(b, 5): Weg 8, 3, 6, 4 -> rechts von 4");
            Suchbaum.einfuegen(b, 11);
            assertEquals("8(3(1,6(4(-,5),7)),10(-,14(13(11,-),-)))", Testhilfe.klammer(b), "einfuegen(b, 11): Weg 8, 10, 14, 13 -> links von 13");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

