            BinTree b = Suchbaum.baueAus(werte);
            assertTrue(b != null, "baueAus liefert null - erzeuge mit new BinTree() einen NEUEN (leeren) Baum und fuege ein");
            assertEquals("8(3(1,6(4,7)),10(-,14(13,-)))", Testhilfe.klammer(b), "baueAus({8, 3, 10, 1, 6, 14, 4, 7, 13}): beispielBST");
            int[] kette = {1, 2, 3, 4, 5};
            assertEquals(Testhilfe.klammer(Baumschule.entartet()), Testhilfe.klammer(Suchbaum.baueAus(kette)), "baueAus({1, 2, 3, 4, 5}): sortierte Werte -> entarteter Baum");
            int[] doppelt = {5, 3, 5, 8, 3};
            assertEquals("5(3,8)", Testhilfe.klammer(Suchbaum.baueAus(doppelt)), "baueAus({5, 3, 5, 8, 3}): Duplikate werden ignoriert");
            BinTree leer = Suchbaum.baueAus(new int[0]);
            assertTrue(leer != null, "baueAus mit leerer Reihung: leerer Baum, nicht null");
            assertTrue(leer.isEmpty(), "baueAus mit leerer Reihung: leerer Baum");
            assertTrue(Suchbaum.baueAus(werte) != b, "Jeder Aufruf von baueAus muss einen NEUEN Baum erzeugen");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void experte_istBST() {
        try {
            assertTrue(Suchbaum.istBST(Baumschule.beispielBST()), "istBST(beispielBST): true");
            assertTrue(Suchbaum.istBST(Baumschule.entartet()), "istBST(entartet): true");
            assertTrue(Suchbaum.istBST(Baumschule.blatt(0)), "istBST eines Blatts: true");
            assertTrue(Suchbaum.istBST(Baumschule.leer()), "istBST des leeren Baums: true");
            assertFalse(Suchbaum.istBST(Baumschule.zahlenbaum()), "istBST(zahlenbaum): false (9 links von 5)");
            BinTree falle1 = Baumschule.knoten(8, Baumschule.knoten(3, Baumschule.blatt(1), Baumschule.blatt(9)), Baumschule.blatt(10));
            assertFalse(Suchbaum.istBST(falle1), "istBST(8(3(1,9),10)): false - 9 > 3 passt zum Elternknoten, steht aber im LINKEN Teilbaum der 8 (nur Kinder pruefen reicht nicht!)");
            BinTree falle2 = Baumschule.knoten(8, Baumschule.blatt(3), Baumschule.knoten(10, Baumschule.blatt(5), Baumschule.blatt(14)));
            assertFalse(Suchbaum.istBST(falle2), "istBST(8(3,10(5,14))): false - 5 steht im RECHTEN Teilbaum der 8");
            assertFalse(Suchbaum.istBST(Baumschule.knoten(5, Baumschule.blatt(5), Baumschule.leer())), "istBST(5(5,-)): false - keine Duplikate");
            assertFalse(Suchbaum.istBST(Baumschule.knoten(5, Baumschule.leer(), Baumschule.blatt(5))), "istBST(5(-,5)): false - keine Duplikate");
            assertTrue(Suchbaum.istBST(Baumschule.knoten(0, Baumschule.leer(), Baumschule.blatt(1))), "istBST(0(-,1)): true (die 0 ist erlaubt)");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void experte_ausgeglichenAus() {
        try {
            int[] neun = {1, 3, 4, 6, 7, 8, 10, 13, 14};
            BinTree b = Suchbaum.ausgeglichenAus(neun);
            assertTrue(b != null, "ausgeglichenAus liefert null");
            assertEquals("7(3(1,4(-,6)),10(8,13(-,14)))", Testhilfe.klammer(b), "ausgeglichenAus({1, 3, 4, 6, 7, 8, 10, 13, 14}): mitte = (lo + hi) / 2 als Wurzel, Haelften rekursiv");
            int[] sieben = {1, 2, 3, 4, 5, 6, 7};
            assertEquals("4(2(1,3),6(5,7))", Testhilfe.klammer(Suchbaum.ausgeglichenAus(sieben)), "ausgeglichenAus({1, ..., 7}): vollstaendiger Baum mit 3 Ebenen");
            int[] fuenf = {1, 2, 3, 4, 5};
            assertEquals("3(1(-,2),4(-,5))", Testhilfe.klammer(Suchbaum.ausgeglichenAus(fuenf)), "ausgeglichenAus({1, ..., 5}): Hoehe 3 statt 5 wie beim entarteten Baum");
            int[] eins = {42};
            assertEquals("42", Testhilfe.klammer(Suchbaum.ausgeglichenAus(eins)), "ausgeglichenAus({42}): ein Blatt");
            BinTree leer = Suchbaum.ausgeglichenAus(new int[0]);
            assertTrue(leer != null, "ausgeglichenAus der leeren Reihung: leerer Baum, nicht null");
            assertTrue(leer.isEmpty(), "ausgeglichenAus der leeren Reihung: leerer Baum");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }

    @Test
    public void experte_nachfolger() {
        try {
            BinTree b = Baumschule.beispielBST();
            assertEquals(10, Suchbaum.nachfolger(b, 8), "nachfolger(beispielBST, 8): 10 (kleinster Wert im rechten Teilbaum)");
            assertEquals(8, Suchbaum.nachfolger(b, 7), "nachfolger(beispielBST, 7): 8 - die 7 hat keinen rechten Teilbaum, der Nachfolger steht WEITER OBEN");
            assertEquals(-1, Suchbaum.nachfolger(b, 14), "nachfolger(beispielBST, 14): -1 (14 ist das Maximum)");
            assertEquals(6, Suchbaum.nachfolger(b, 4), "nachfolger(beispielBST, 4): 6");
            assertEquals(4, Suchbaum.nachfolger(b, 3), "nachfolger(beispielBST, 3): 4");
            assertEquals(13, Suchbaum.nachfolger(b, 10), "nachfolger(beispielBST, 10): 13");
            assertEquals(6, Suchbaum.nachfolger(b, 5), "nachfolger(beispielBST, 5): 6 (5 steht nicht im Baum)");
            assertEquals(1, Suchbaum.nachfolger(b, 0), "nachfolger(beispielBST, 0): 1");
            assertEquals(13, Suchbaum.nachfolger(b, 12), "nachfolger(beispielBST, 12): 13");
            assertEquals(4, Suchbaum.nachfolger(Baumschule.entartet(), 3), "nachfolger(entartet, 3): 4");
            assertEquals(-1, Suchbaum.nachfolger(Baumschule.leer(), 8), "nachfolger im leeren Baum: -1");
            assertEquals("8(3(1,6(4,7)),10(-,14(13,-)))", Testhilfe.klammer(b), "nachfolger darf den Baum NICHT veraendern");
        } catch (RuntimeException e) {
            Testhilfe.laufzeitfehler(e);
        }
    }
}

